// Uganda price list, straight from uCRM via the plugin's public feed.
// Shape: { currency, vat_note, plans:[{name,price,period,speed}], hardware:[{name,price}] }
let feed = {};
try { feed = $('Load Products').first().json || {}; } catch (e) { feed = {}; }

const cur   = String(feed.currency || 'UGX');
const plans = Array.isArray(feed.plans) ? feed.plans : [];
const hw    = Array.isArray(feed.hardware) ? feed.hardware : [];

const money = (v) => cur + ' ' + Number(v).toLocaleString('en-UG');
const lines = [];
for (const p of plans) {
  if (!p || !p.name || p.price == null) continue;
  lines.push('- ' + p.name + ': ' + money(p.price) + ' per month (RECURRING)' +
             (p.speed ? ' - ' + p.speed : ''));
}
for (const h of hw) {
  if (!h || !h.name || h.price == null) continue;
  lines.push('- ' + h.name + ': ' + money(h.price) + ' ONE-TIME');
}

// No list means quote nothing. Inventing a price is worse than saying "let me
// confirm" - the plugin's own assistant quoted a kit price and then handed off,
// which is how a customer ends up holding two different numbers.
const priceList = lines.length
  ? lines.join(String.fromCharCode(10)) +
    String.fromCharCode(10) + '(All prices VAT inclusive. Monthly and one-time are separate - never add them together.)'
  : 'PRICE LIST UNAVAILABLE - do not quote any price. Tell the customer you will confirm it and route to Sales +256 703 834 115.';

let contactContext = 'CONTACT CONTEXT: unknown contact - treat as a new prospect (normal sales flow).';
try {
  let e = {}; try { e = $('Signal Engine').first().json || {}; } catch (err) {}
  let s = {}; try { s = $('State Upsert').first().json || {}; } catch (err) {}
  const isCust = (e.is_customer === true) || (s.is_customer === true);
  const st  = String(s.state || e.state || 'PROSPECT');
  const nm  = String(e.customer_name || '').trim();
  const sv  = String(e.customer_service || '').trim();
  if (isCust) {
    contactContext = 'CONTACT CONTEXT: EXISTING DISHNET CUSTOMER' +
      (nm ? (' - ' + nm) : '') + (sv ? (' - service: ' + sv) : '') +
      '. SUPPORT/SERVICE MODE: do NOT pitch or upsell. Funnel state: ' + st + '.';
  }
} catch (e) {}

let finalInput = '';
try { finalInput = String($('Concatenate Messages').first().json.finalInput || ''); } catch (e) {}

return [{ json: { priceList, contactContext, finalInput, currency: cur } }];

