// DishNet Extract Markers — v2.
// v2 additions:
//   1. DETERMINISTIC TICKET FALLBACK — if the AI reply carries no [TICKET] block but
//      the customer's combined message (INCLUDING voice-note transcripts, which the
//      raw Signal Engine never sees) is clearly a support complaint AND the contact is
//      a known customer (or already past payment), a ticket object is synthesized so
//      the existing Insert Ticket -> Notify Support pipeline runs anyway. The v2
//      Insert Ticket SQL dedupes to one Open ticket per phone per 24h.
//   2. CUSTOMER LEAD DAMPING — known customers no longer generate sales leads from
//      weak signals (price / coverage / product words). Only genuine buy / upgrade /
//      callback intent (or an explicit AI [LEAD]) creates a lead for an existing
//      customer, so sales stops being pinged about people we already serve.

function grab(text, tag){
  const re = new RegExp('\\['+tag+'\\]([\\s\\S]*?)\\[\\/'+tag+'\\]');
  const m = text.match(re);
  let obj = null, seen = false;
  if (m){ seen = true; try { obj = JSON.parse(m[1].trim()); } catch(e){ obj = {}; } }
  return { seen, obj };
}

// Deterministic lead scorer. Returns {scoreDelta, intents[], forceHot, product} or null.
// Support-context aware: complaint phrases never create a sales lead on their own, but a
// genuine forward-looking signal still scores even inside a complaint.
function scoreSignals(msg){
  const t = (msg || '').toLowerCase();
  if (!t.trim()) return null;

  const has = (arr) => arr.some(k => t.includes(k));

  const support = ['internet down','internet is down','net down','no internet','no connection',
    'no signal','no network','slow internet','internet slow','slow net','outage','network problem',
    'network issue','connection problem','connection issue','service not working','not working',
    'stopped working','not connecting','keeps disconnecting','disconnecting','disconnected','offline',
    'down again','billing issue','billing problem','invoice problem','invoice issue','wrong bill',
    'overcharged','double charged','refund','complaint'];

  const callback = ['call me','call back','callback','ring me','please call','contact me',
    'someone call','sales call','have someone','want sales to call','talk to someone'];
  const buy      = ['want to order','can i order','place order','i want to buy','want to buy'];
  const pay      = ['where to pay','where do i pay','how do i pay','how to pay','how can i pay',
    'ready to pay','make payment','send payment','want to pay'];
  const install  = ['when can you install','when install','installation date','how soon','install date'];
  const stock    = ['do you have stock','in stock','is it available','availability'];
  const upgrade  = ['upgrade','faster plan','faster speed','more speed','better plan','higher plan',
    'add line','second line','another line','second connection','another connection','more bandwidth','extra speed'];
  const business = ['hotspot','reseller','cafe','caf\u00e9','office internet','hotel internet',
    'school internet','ngo','business internet','for my office','for my hotel','for my shop'];
  const coverage = ['coverage','do you cover','cover my area','available in','reach my area'];
  const price    = ['price','how much','cost','rate','charge','kitne','bei','monthly','subscription','package','plan'];
  const product  = ['starlink','fiber','fibre','wifi','wi-fi','internet'];

  const isSupport = has(support);

  const hitBuy      = has(buy);
  const hitPay      = has(pay);
  const hitUpgrade  = has(upgrade);
  const hitBusiness = has(business);
  const hitCoverage = has(coverage);
  const hitPrice    = has(price);
  const hitInstall  = has(install);
  const hitStock    = has(stock);
  const hitCallback = has(callback) && !isSupport;
  const hitProduct  = has(product)  && !isSupport;

  const strongSales = hitBuy || hitPay || hitUpgrade || hitBusiness || hitCoverage ||
                      hitPrice || hitInstall || hitStock;

  if (isSupport && !strongSales && !hitCallback) return null;

  let score = 0; const intents = []; let forceHot = false;
  function add(pts, name){ score += pts; intents.push(name); }

  if (hitCallback){ add(50,'callback'); forceHot = true; }
  if (hitBuy)     { add(40,'buy_intent'); forceHot = true; }
  if (hitPay)     { add(40,'payment'); forceHot = true; }
  if (hitInstall) { add(30,'install_timeline'); }
  if (hitStock)   { add(30,'stock_check'); }
  if (hitUpgrade) { add(25,'upgrade'); }
  if (hitBusiness){ add(20,'business_inquiry'); }
  if (hitCoverage){ add(10,'coverage'); }
  if (hitPrice)   { add(5,'price'); }
  if (hitProduct) { add(5,'product_interest'); }

  let prod = '';
  if (t.includes('starlink')) prod = 'Starlink';
  else if (t.includes('fiber') || t.includes('fibre')) prod = 'Fiber';
  else if (t.includes('hotspot')) prod = 'Hotspot';
  else if (t.includes('reseller')) prod = 'Reseller';
  else if (t.includes('ruijie') || t.includes('access point') || t.includes('reyee')) prod = 'Ruijie';
  else if (t.includes('mikrotik') || t.includes('mikro tik') || t.includes('l009') || t.includes('rb951') || t.includes('hex router') || t.includes('routeros')) prod = 'MikroTik';

  if (score <= 0 && !forceHot) return null;
  return { scoreDelta: score, intents, forceHot, product: prod };
}

// v2: support / callback detection for the ticket fallback (voice transcripts included)
const TICKET_SUPPORT_RE = /\b(not\s*working|no\s*internet|internet\s*(is\s*)?down|no\s*connection|can'?t\s*connect|cannot\s*connect|disconnect(ed)?|offline|no\s*signal|very\s*slow|slow\s*internet|internet\s*slow|slow\s*net|buffering|outage|down\s*again|stopped\s*working|not\s*connecting|keeps?\s*dropping|complain(t|ing)?|refund|overcharged|double\s*charged|wrong\s*(bill|amount)|no\s*service|service\s*(is\s*)?(off|expired|suspended)|expired|suspend(ed)?|reconnect\s*me|help\s*me\s*connect|having\s*(an?\s*)?(issue|problem|trouble)|network\s*(problem|issue))\b/i;
const TICKET_CALLBACK_RE = /\b(call\s*me|ring\s*me|call\s*back|callback|phone\s*me|please\s*call|give\s*me\s*a\s*call|have\s*(someone|somebody|sales|support)\s*call)\b/i;

function synthTicket(userMsg, aiTicketSeen, isCustomer, stateRank){
  if (aiTicketSeen) return null;                                  // AI already emitted one
  if (!(isCustomer || (Number(stateRank)||0) >= 5)) return null;  // customers / post-payment only
  const t = String(userMsg||'');
  if (!TICKET_SUPPORT_RE.test(t)) return null;
  return { issue: t.slice(0,200), priority: TICKET_CALLBACK_RE.test(t) ? 'High' : 'Normal' };
}

// v2.1: product photo requests ("send me photo", "what does it look like")
const IMAGE_REQ_RE = /\b(photo|photos|picture|pictures|image|images|pic|pics|foto)\b|what\s*does\s*(it|the\s*\w+)\s*look\s*like|how\s*(does|do)\s*(it|they)\s*look|show\s*me\s*(the|a|your)?\s*(kit|dish|device|router|product)|can\s*i\s*see\s*(it|the)\b/i;
function productFromText(msg){
  const t = String(msg||'').toLowerCase();
  // 1. exact model token (works for any catalog naming: rap2260(g), ew1300g, rb951, l009, hex...)
  const m = t.match(/\b(?:rg[\s-]*)?((?:rap|ew|es)[\s-]*\d{3,4}(?:\s*\([a-z]\)|[a-z])?|rb[\s-]*\d{3,4}[a-z-]*|l009[a-z0-9-]*|hex(?:\s?s)?\b|750gr3)/i);
  if (m) return m[1];
  // 2. keyword tiers
  if (/\bmini\b/.test(t)) return 'mini';
  if (/\bstandard\b|\bbig(ger)?\b|\blarge\b/.test(t)) return 'standard';
  if (/mikrotik|mikro\s*tik|routeros/.test(t)) return 'mikrotik';
  if (/ruijie|reyee|access\s*point|ceiling\s*ap|outdoor\s*ap|wall\s*ap/.test(t)) return 'ruijie';
  if (/nano\s*station|ubiquiti|extender/.test(t)) return 'nanostation';
  if (/poe\s*switch|\bswitch\b/.test(t)) return 'switch';
  if (/\brouter\b/.test(t)) return 'router';
  if (/fiber|fibre/.test(t)) return 'fiber';
  if (/starlink|\bdish\b|\bkit\b/.test(t)) return 'starlink';
  return '';
}

// v2.8: HANDOFF GUARANTEE - if the AI reply promises that a human will contact the
// customer, sales MUST be pinged deterministically (no reliance on [LEAD]/[ORDER]).
const HANDOFF_RE = /(?:sales|support|accounts|our)\s+team\s+(?:will|shall)\s+(?:reach|contact|call|get\s+back)|will\s+(?:reach\s+out|contact\s+you|call\s+you|be\s+in\s+touch|get\s+back\s+to\s+you)|reach(?:ing)?\s+out\s+(?:to\s+you\s+)?(?:shortly|within|soon)|have\s+(?:someone|our\s+team|sales|support)\s+(?:call|contact|message)\s+you|putting\s+you\s+in\s+touch|loop\s+(?:our|the)\s+\w+\s*(?:team\s*)?in|they'?ll\s+(?:reach\s+out|contact|call)/i;

// ==== n8n glue (do not edit above this line without re-running qa_extract_markers.test.js) ====
const items = $input.all();
const jid = ($('Parse Message Data').first().json.remoteJid || '');
const senderPhone = ($('Parse Message Data').first().json.realPhone || jid.split('@')[0].replace(/[^0-9]/g, ''));
const pushName = $('Parse Message Data').first().json.pushName || '';

let userMsg = '';
try { userMsg = String($('Concatenate Messages').first().json.finalInput || ''); } catch(e){ userMsg = ''; }

// v2: contact identity from the deterministic engine (same execution, survives Wait resume)
let isCustomer = false, stateRank = 0;
try {
  let se = {}; try { se = $('Signal Engine').first().json || {}; } catch(err) {}
  isCustomer = !!se.is_customer;
  stateRank = Number(se.state_rank) || 0;
} catch(e) {}

return items.map(it => {
  let text = (it.json.output || '').toString();
  const ord = grab(text,'ORDER');
  const led = grab(text,'LEAD');
  const tic = grab(text,'TICKET');
  const img = grab(text,'IMAGE');
  const handoffHit = HANDOFF_RE.test(text);

  const o = ord.obj || {}, l = led.obj || {}, t = tic.obj || {};

  // ---------- v2 DETERMINISTIC TICKET FALLBACK ----------
  const synth = synthTicket(userMsg, tic.seen, isCustomer, stateRank);
  if (synth){
    tic.seen = true;
    t.name = t.name || pushName;
    t.service = t.service || '';
    t.issue = synth.issue;
    t.priority = synth.priority;
  }

  // ---------- v2.1 PRODUCT IMAGE REQUEST ----------
  // AI [IMAGE] marker wins; deterministic regex catches it when the AI forgets.
  let imageFound = false, imageProduct = '';
  if (img.seen || IMAGE_REQ_RE.test(userMsg)){
    imageProduct = String(((img.obj||{}).product) || '').trim().slice(0,60) || productFromText(userMsg);
    imageFound = imageProduct !== '';
  }

  // ---------- v3.0 SPECIAL-ORDER DIRECT IMAGE (whitelisted hosts only) ----------
  let imageDirect = null;
  const iu = String((img.obj || {}).url || '');
  if (img.seen && /^https:\/\/([a-z0-9.-]*\.)?(jumia\.is|dishnetuganda\.com|eo-sgp-cos\.ruijie\.com|i\.mt\.lv|serpapi\.com|gstatic\.com|googleusercontent\.com|google\.com)\//i.test(iu)) {
    imageDirect = { name: String((img.obj || {}).product || 'Special-order item').slice(0, 80),
                    url: iu, price: Number((img.obj || {}).price) || 0 };
    imageFound = true;
  }

  // ---------- LEAD SCORING ----------
  let scoreDelta = 0; let intents = []; let forceHot = false;
  const sig = scoreSignals(userMsg);   // support-aware: pure complaints return null
  if (sig){
    scoreDelta = sig.scoreDelta;
    intents = sig.intents.slice();
    forceHot = sig.forceHot;
    if (!l.product && sig.product) l.product = sig.product;
  }

  // Honour an explicit AI [LEAD]
  if (led.seen){
    const aiStage = String(l.stage || '').toUpperCase();
    if (aiStage === 'HOT'){ forceHot = true; }
    else if (aiStage === 'WARM'){ scoreDelta = Math.max(scoreDelta, 21); }
    else { scoreDelta = Math.max(scoreDelta, 1); }
    if (intents.indexOf('ai_lead') === -1) intents.push('ai_lead');
  }

  // Location pin = strong buying signal (unless this turn is a support ticket)
  const hasPin = /google\.com\/maps|maps\?q=|maps\.app\.goo\.gl|degreeslatitude/i.test(userMsg);
  if (hasPin && !tic.seen){
    forceHot = true;
    scoreDelta += 20;
    if (intents.indexOf('location_pin') === -1) intents.push('location_pin');
    if (!l.pin){ const m = userMsg.match(/https?:\/\/\S*maps\S+/i); if (m) l.pin = m[0]; }
  }

  // ---------- v2 CUSTOMER LEAD DAMPING ----------
  if (isCustomer){
    const strong = intents.some(i => ['buy_intent','payment','upgrade','callback','ai_lead','location_pin'].indexOf(i) !== -1);
    if (!strong){ scoreDelta = 0; forceHot = false; intents = []; }
  }

  const leadFound = (scoreDelta > 0) || forceHot || led.seen;

  text = text.replace(/\[(ORDER|LEAD|TICKET|IMAGE)\][\s\S]*?\[\/(ORDER|LEAD|TICKET|IMAGE)\]/g, '').trim();
  text = text.replace(/\[(ORDER|LEAD|TICKET|IMAGE)\][\s\S]*$/i, '').trim();
  const when = new Date().toLocaleString('en-GB', { timeZone: 'Africa/Kampala' });

  // ---------- ORDER alert ----------
  let staffMessage = '';
  if (ord.seen){
    staffMessage = 'NEW ORDER - DishNet\n\nCustomer: ' + (o.name || pushName) +
      '\nPhone: ' + senderPhone + '\nProduct: ' + (o.product || '') +
      '\nPlan: ' + (o.plan || '') + '\nTotal: USD ' + (o.total_usd || '') +
      '\nLocation: ' + (o.location || 'see chat') + '\nPayment: ' + (o.payment || '') +
      '\nTime: ' + when;
  }

  // ---------- TICKET alert ----------
  let ticketAlert = '';
  if (tic.seen){
    ticketAlert = 'NEW TICKET - DishNet\n\nCustomer: ' + (t.name || pushName) +
      '\nPhone: ' + senderPhone + '\nService: ' + (t.service || '') +
      '\nIssue: ' + (t.issue || '') + '\nPriority: ' + (t.priority || 'Normal') +
      (synth ? '\nSource: deterministic auto-detect (AI missed it)' : '') +
      (isCustomer ? '\nKnown customer: YES' : '') +
      '\nTime: ' + when + '\nChat: https://wa.me/' + senderPhone;
  }

  return { json: { output: text, remoteJid: jid, senderPhone, pushName,
    orderFound: ord.seen, order: o, staffMessage,
    leadFound, lead: l, scoreDelta, intents, forceHot,
    ticketFound: tic.seen, ticket: t, ticketAlert,
    imageFound, imageProduct, imageDirect,
    handoffPromised: handoffHit && !ord.seen && !tic.seen,
    handoffAlert: 'BOT PROMISED FOLLOW-UP - DishNet' +
      String.fromCharCode(10) + String.fromCharCode(10) +
      'Customer: ' + pushName + ' (' + senderPhone + ')' + String.fromCharCode(10) +
      'The bot told them our team will contact them - please action.' + String.fromCharCode(10) +
      'Customer said: "' + (userMsg || '').slice(0, 150) + '"' + String.fromCharCode(10) +
      'Bot replied: "' + text.slice(0, 150) + '"' + String.fromCharCode(10) +
      'Chat: https://wa.me/' + senderPhone } };
});

const j = $input.first().json || {};
let n = (j.value != null) ? j.value : (j['ug:order_seq'] != null ? j['ug:order_seq'] : null);
if (n == null) { for (const k in j) { if (typeof j[k] === 'number') { n = j[k]; break; } } }
n = parseInt(n, 10);
if (!n || isNaN(n)) n = Date.now() % 100000;
return [{ json: { orderNo: n, orderNoStr: 'DN-' + n } }];

// EDIT: staff WhatsApp numbers that receive new-order alerts
const numbers = [];  // REQUIRED: Uganda staff numbers, e.g. ["2567XXXXXXXX"]. Empty means this alert sends to nobody.
const msg = ($('Format Order No').first().json.orderNoStr || '') + '\n' + ($('Extract Markers').first().json.staffMessage || '');
return numbers.map(n => ({ json: { staffNumber: n + '@s.whatsapp.net', staffMessage: msg } }));

// DishNet Use Cached Price — v2 (converted from Set to Code node so the CONTACT
// CONTEXT line can be built with a safe try/catch, same as Format Price List).
let priceList = '';
try { priceList = String($json.priceList || ''); } catch(e) {}

let contactContext = 'CONTACT CONTEXT: unknown contact - treat as a new prospect (normal sales flow).';
try {
  let e = {}; try { e = $('Signal Engine').first().json || {}; } catch(err) {}
  let s = {}; try { s = $('State Upsert').first().json || {}; } catch(err) {}
  const isCust = (e.is_customer === true) || (s.is_customer === true);
  const st = String(s.state || e.state || 'PROSPECT');
  const sup = (e.support_open === true) || (s.support_open === true);
  const nm = String(e.customer_name || '').trim();
  const sv = String(e.customer_service || '').trim();
  if (isCust) {
    contactContext = 'CONTACT CONTEXT: EXISTING DISHNET CUSTOMER' + (nm ? (' - ' + nm) : '') + (sv ? (' - service: ' + sv) : '') +
      '. SUPPORT/SERVICE MODE: do NOT pitch or upsell. Funnel state: ' + st + '. Open support: ' + (sup ? 'YES' : 'no') + '.';
  } else {
    contactContext = 'CONTACT CONTEXT: not a known customer (prospect). Funnel state: ' + st + '. Normal sales flow.';
  }
} catch(err) {}

return [{ json: { finalInput: $('Concatenate Messages').first().json.finalInput, priceList, contactContext } }];

// HOT-only sales alert. WARM/COLD stay silent (dashboard only).
const numbers = [];  // REQUIRED: Uganda staff numbers, e.g. ["2567XXXXXXXX"]. Empty means this alert sends to nobody.
const j = $json;
const phone = ($('Extract Markers').first().json.senderPhone) || j.phone || '';
const name  = j.name || $('Extract Markers').first().json.pushName || '';
let latest = '';
try { latest = String($('Concatenate Messages').first().json.finalInput || ''); } catch(e){}
const when = new Date().toLocaleString('en-GB', { timeZone: 'Africa/Kampala' });
const msg = 'HOT LEAD - DishNet\n\nName: ' + name +
  '\nPhone: ' + phone +
  '\nInterest: ' + (j.product || '') +
  '\nLocation: ' + (j.location || '') +
  '\nScore: ' + (j.score != null ? j.score : '') +
  '\nLatest: ' + latest.slice(0,200) +
  '\nTime: ' + when +
  '\nChat: https://wa.me/' + phone;
return numbers.map(n => ({ json: { staffNumber: n + '@s.whatsapp.net', staffMessage: msg } }));

// EDIT: support staff WhatsApp numbers that receive new-ticket alerts
const numbers = [];  // REQUIRED: Uganda staff numbers, e.g. ["2567XXXXXXXX"]. Empty means this alert sends to nobody.
const msg = $('Extract Markers').first().json.ticketAlert || '';
return numbers.map(n => ({ json: { staffNumber: n + '@s.whatsapp.net', staffMessage: msg } }));

// DishNet deterministic Signal Scanner + Conversation State Engine — v2.
// v2 changes (vs v1):
//   1. COOLDOWN RE-ALERTS — sticky flags no longer swallow repeat signals forever.
//      A customer who asks for a callback again AFTER the cooldown window gets a
//      FRESH alert (v1 alerted only on the first-ever transition, then went silent).
//   2. CUSTOMER AWARENESS — prior.is_customer now comes from ug_customers (nightly
//      UCRM sync). Known customers are pinned at ACTIVE_CUSTOMER rank, never re-enter
//      the lead funnel, never trigger HOT-lead alerts, and their callbacks route to
//      SUPPORT instead of sales.
//   3. Emits fire_* booleans so State Upsert refreshes per-signal timestamps, which
//      anchor the cooldowns.

const RANK = { PROSPECT:1, LEAD:2, HOT_LEAD:3, CALLBACK_REQUESTED:4, PAYMENT_SENT:5,
  INSTALLATION_PENDING:6, INSTALLATION_SCHEDULED:7, KIT_RECEIVED:8, ACTIVATION_PENDING:9, ACTIVE_CUSTOMER:10 };
const NAME = Object.fromEntries(Object.entries(RANK).map(([k,v])=>[v,k]));

// Re-alert cooldowns in HOURS per signal. Within the window, repeats stay silent;
// after it, the same signal fires a fresh alert and refreshes its timestamp.
const COOLDOWN_H = { callback:4, payment:24, install:24, kit:48, activation:12, support:24 };

const PAT = {
  payment_confirmed: /\b(i\s*(have\s*)?paid|payment\s*(sent|made|done|complete)|paid\s*(you|now|already|for|it)|sent\s*(you\s*)?(the\s*)?(payment|money|cash|funds)|here'?s?\s*(is\s*)?(my|the)\s*receipt|receipt\s*(is\s*)?(attached|below|here)|transferred|deposited|i\s*sent\s*(it|the\s*money))\b/i,
  payment_intent: /\b(how\s*(do\s*i|to|can\s*i)?\s*pay|where\s*(do\s*i|to|can\s*i)\s*pay|want\s*to\s*pay|ready\s*to\s*pay|can\s*i\s*pay|payment\s*(method|details|number|account|through|option|plan)|pay\s*(via|with|by|in)\b|how\s*do\s*i\s*send\s*money|instal?ment|first\s*payment|down\s*payment|deposit\s*how)\b/i,
  callback: /\b(call\s*me|ring\s*me|call\s*back|callback|phone\s*me|give\s*me\s*a\s*call|can\s*(you|we|i)\s*(just\s*)?(have\s*a\s*)?call|have\s*(sales|someone|somebody)\s*call|please\s*call|(want|need|book|schedule)\s*a\s*call|(waiting|wait)\s*for\s*(your|the)\s*call|expecting\s*(your|a)\s*call|let'?s\s*(have\s*)?a?\s*call)\b/i,
