  buy_strong: /\b(i\s*want\s*to\s*(buy|order|subscribe)|place\s*(an\s*)?order|i'?ll\s*take\s*(it|the)|book\s*(it|me)|sign\s*me\s*up|let'?s\s*proceed|go\s*ahead)\b/i,
