};

function detectSignals(text, messageType) {
  const t = String(text || '');
  const s = {};
  for (const k in PAT) s[k] = PAT[k].test(t);
  s.location_pin = /location/i.test(String(messageType||'')) || s.location_text;
  const kitMatch = t.match(/\bKIT[A-Z0-9]{4,}\b/i);
  s.kit_number = kitMatch ? kitMatch[0].toUpperCase() : '';
  return s;
}

// Deterministic: highest-priority funnel signal this message -> candidate state.
function candidateState(s) {
  if (s.activation)        return 'ACTIVATION_PENDING';
  if (s.kit)               return 'KIT_RECEIVED';
  if (s.install)           return 'INSTALLATION_PENDING';
  if (s.payment_confirmed) return 'PAYMENT_SENT';
  if (s.callback)          return 'CALLBACK_REQUESTED';
  if (s.location_pin || s.office_visit) return 'HOT_LEAD';
  if (s.payment_intent || s.buy_strong) return 'HOT_LEAD';
  if (s.commercial)        return 'LEAD';
  return 'PROSPECT';
}

function hoursSince(ts, nowMs) {
  if (!ts) return 1e9;
  const t = new Date(ts).getTime();
  return isNaN(t) ? 1e9 : (nowMs - t) / 3600000;
}

function runEngine(messageText, prior, messageType, nowMs) {
  prior = prior || {};
  nowMs = nowMs || Date.now();
  const s = detectSignals(messageText, messageType);
  const isCustomer = !!prior.is_customer;

  // Funnel ratchet (never regress). v2: known customers are pinned at the top so they
  // can never be re-classified as leads/prospects.
  let curRank = RANK[prior.state] || (s.commercial || s.callback || s.payment_confirmed || s.install || s.kit || s.activation ? 0 : 1);
  if (isCustomer) curRank = Math.max(curRank, RANK.ACTIVE_CUSTOMER);
  const eligiblePostSale = (curRank >= RANK.PAYMENT_SENT) || isCustomer;
  let cand = candidateState(s);
  if (!eligiblePostSale && (cand === 'INSTALLATION_PENDING' || cand === 'KIT_RECEIVED' || cand === 'ACTIVATION_PENDING')) {
    cand = (s.payment_intent || s.buy_strong || s.callback) ? 'HOT_LEAD' : 'LEAD';
  }
  const newRank = Math.max(curRank, RANK[cand]);
  let state = NAME[newRank] || 'PROSPECT';

  // Support is a parallel lane (never loses funnel position); surfaces as the state
  // only for pure prospects.
  const supportOpen = !!s.support || !!prior.support_open;
  if (s.support && newRank <= RANK.LEAD) state = 'SUPPORT_REQUEST';

  // Sticky flags: long-term memory of what this contact has ever signalled.
  const flags = {
    callback_requested: !!s.callback || !!prior.callback_requested,
    payment_signal:     !!s.payment_confirmed || !!prior.payment_signal,
    install_signal:     !!s.install || !!prior.install_signal,
    kit_signal:         !!s.kit || !!prior.kit_signal,
    activation_signal:  !!s.activation || !!prior.activation_signal,
    support_open:       supportOpen,
  };
  const kit_number = s.kit_number || prior.kit_number || '';

  // v2 ALERT GATE: signal present in THIS message AND (never flagged before OR the
  // per-signal cooldown has elapsed since the last time we alerted on it).
  const fire = {
    callback:   !!s.callback          && (!prior.callback_requested || hoursSince(prior.callback_at, nowMs)   >= COOLDOWN_H.callback),
    payment:    !!s.payment_confirmed && (!prior.payment_signal     || hoursSince(prior.payment_at, nowMs)    >= COOLDOWN_H.payment),
    install:    !!s.install           && (!prior.install_signal     || hoursSince(prior.install_at, nowMs)    >= COOLDOWN_H.install),
    kit:        !!s.kit               && (!prior.kit_signal         || hoursSince(prior.kit_at, nowMs)        >= COOLDOWN_H.kit),
    activation: !!s.activation        && (!prior.activation_signal  || hoursSince(prior.activation_at, nowMs) >= COOLDOWN_H.activation),
    support:    !!s.support           && (!prior.support_open       || hoursSince(prior.support_at, nowMs)    >= COOLDOWN_H.support),
  };

  const alerts = [];
  if (fire.callback) alerts.push({type:'CALLBACK', lane: isCustomer ? 'support' : 'sales', priority:'HOT', customer:isCustomer});
  if (fire.payment)  alerts.push({type:'PAYMENT',  lane:'accounts', priority:'HOT', customer:isCustomer});
  if (fire.install && eligiblePostSale) alerts.push({type:'INSTALL', lane:'ops', customer:isCustomer});
  if (fire.kit)        alerts.push({type:'KIT', lane:'ops', customer:isCustomer});
  if (fire.activation) alerts.push({type:'ACTIVATION', lane:'ops', customer:isCustomer});
  if (fire.support)    alerts.push({type:'SUPPORT', lane:'support', customer:isCustomer});

  // HOT-lead entry alert: NON-customers only. A known customer is never a "lead"
  // for the sales team; their needs route through support/accounts/ops lanes.
  const wasHot = (RANK[prior.state]||0) >= RANK.HOT_LEAD || isCustomer;
  const isHot = newRank >= RANK.HOT_LEAD;
  if (!isCustomer && isHot && !wasHot && !fire.callback && !fire.payment) {
    const ht = s.location_pin ? 'LOCATION_PIN' : (s.office_visit ? 'OFFICE_VISIT' : 'HOT_LEAD');
    alerts.push({type:ht, lane:'sales', priority:'HOT', customer:false});
  }

  const isLead = !isCustomer && newRank >= RANK.LEAD;

  return { signals:s, state, state_rank:newRank, flags, kit_number, alerts, is_lead:isLead, fire, is_customer:isCustomer };
}

// ==== n8n glue (do not edit above this line without re-running qa_signal_engine.test.js) ====
const prior=$json||{}; const P=$('Parse Message Data').item.json; const msg=P.messageText||'';
const r=runEngine(msg,prior,P.messageType,Date.now());
return { json: { phone:P.realPhone, remoteJid:P.remoteJid, pushName:P.pushName||'', instance:P.instance, messageText:msg,
