// Flatten UCRM /clients into unique ug_customers rows (skip UCRM leads).
const rows = []; const seen = new Set();
function norm(p){
  let d = String(p||'').replace(/[^0-9]/g,'');
  if (!d) return '';
  if (d.startsWith('00')) d = d.slice(2);
  if (d.length === 10 && d.startsWith('0')) d = '211' + d.slice(1);  // 09xxxxxxxx -> 2119xxxxxxxx
  if (d.length === 9) d = '211' + d;                                  // 9xxxxxxxx  -> 2119xxxxxxxx
  return d.length >= 11 ? d : '';
}
for (const it of $input.all()){
  const c = it.json || {};
  if (c.isLead === true) continue;  // UCRM leads are NOT customers
  const status = c.isArchived === true ? 'archived' : 'active';
  const name = String(c.companyName || ((c.firstName||'') + ' ' + (c.lastName||'')).trim() || '').slice(0,80);
  const phones = [];
  if (Array.isArray(c.contacts)) for (const ct of c.contacts){ if (ct && ct.phone) phones.push(ct.phone); }
  if (c.phone) phones.push(c.phone);
  for (const p of phones){
    const d = norm(p);
    if (!d || seen.has(d)) continue;
    seen.add(d);
    rows.push({ json: { phone: d, name, ucrm_client_id: c.id || null, status } });
  }
}
return rows;

